"""Readable bounded progress; all measured orders, explicit test/archive and FPS limits."""
def report(stats,assertions,choices_assertions,bench,focused,fingerprint):
 n=lambda x:f'{x:,}'.replace(',',' ')
 out=['# Большой проход NPC — 0.15.99','','`██████████████████░░░░░░░░░░░░` **61,62%** точных ключей публичной очереди; полоса округлена.','','| Учёт | До | После |','| --- | ---: | ---: |','| Точные ключи | 9 612 · 59,17% | 10 009 · 61,62% |','| Без подтверждённого точного ключа | 6 632 | 6 235 · 38,38% |','| Всего строк в базе | 16 244 | 16 244 |','','Это не процент готовности всей игры. Очередь включает тестовые, исторические, нейтральные, структурные и редакторские строки; закрытые серверные скрипты не выгружены. Работающий динамический перевод может не иметь отдельного точного ключа.','','## Новые переводы','','397 новых реплик / 40 обозначений говорящего. В том числе 38 телефонных реплик Абифона; 11 групп ответов / 11 подписей / 12 опубликованных оформлений. Связанные разговоры лягушек и всех трёх рассказчиков у костра проверены вместе.','','| Говорящий | Новых ключей |','| --- | ---: |']
 out += [f'| {name} | {count} |' for name,count in stats['new_by_speaker'].items()]
 out += ['| Всего | 397 |','','[Контекстная вычитка и решения переводчика](NPC_0.15.99_REVIEW_NOTES.md) · [Все говорящие и остаток](NPC_ALL_SPEAKERS_0.15.99_RU.md).','','В выбранных 438 строках: 397 новых, 27 прежних, 2 структурные, 1 нейтральная и 11 исключённых из Removed Dialogue. Имена/теги в префиксах сохранены; этот проход не объявляет исправленными все надписи над сущностями.','','36 строк Centauri — тестовый/alpha-сервер и архив объявлений. Три просьбы Pesthunter Pamela помечены alpha в опубликованных условиях. 40 строк четырёх NPC — звуковые реплики, а не 40 содержательных инструкций. Эти ограничения не скрыты за общим процентом.','','## Проверки','',f'На одном окончательном JAR: 167 свежих групп + 15 тестов извлечения. Новый набор реплик: {n(assertions)} проверок; ответы: {n(choices_assertions)}. Проверяется стиль каждого символа, в том числе свежие действия по нажатию, подсказки, курсив, цвета, числа, временные метки, счётчики, дробление компонентов, пользовательские замены и защита чата игроков.','','Все 397 новых ключей дают ожидаемый результат как в обычном, так и в опубликованном цветном виде. Остальные 10 850 строк проверяемой выборки сохранили прежний результат. 72 прежних цветных пробела не объявлены исправленными.','','Сверены 38 страниц текущего публичного API: 37 ревизий совпали; у Honey добавлена только навигационная ссылка до информационного блока. Полные Dialogue, условия и шаблоны совпадают. Зафиксированная очередь не изменена.','','## Производительность','','Сравнение с предыдущим JAR 0.15.98. Исправления оптимизации 0.15.96 сохранены; отклонённые эксперименты 0.15.97 не включены. По уточнению пользователя в игре используется 0.15.96; установленная сборка здесь не менялась.','','Новые реплики объединяются с прежним словарём один раз при запуске, а ответы дополняют существующую таблицу. Новых покадровых проходов, обработчиков сообщений, сетевого перевода и кэша цветных компонентов нет. Проверено совпадение исполняемых инструкций вне стартовой загрузки таблиц и служебных ссылок; остальные классы, включая HUD/F3 и его оптимизации, побайтно совпадают с 98. Размер словаря и расход памяти при загрузке увеличились — нулевая нагрузка не обещается.','','Ниже — изолированные измерения, не FPS, GPU, время кадра или 0,1% lows. Каждый блок: четыре отдельные JVM в порядке 98 → 99 → 99 → 98. Оба порядка и все исходные раунды сохранены. Время относится к сообщению чата либо операции HUD, не ко всему кадру.']
 for name,family in bench['families'].items():
  out+=['',f'### {name}','','| Сценарий | Одинаковая полезная работа | До → после, мкс, два порядка | Изменение | Байты до → после |','| --- | --- | ---: | ---: | ---: |']
  for r in family['summary']:
   equal=r.get('equal_useful_output',not r['mode'].startswith('new_'));times=' / '.join(f'{o["before_ns"]/1000:.3f} → {o["after_ns"]/1000:.3f}' for o in r['orders']);pct=' / '.join(f'{o["wall_change_percent"]:+.1f}%' for o in r['orders']);allocation=' / '.join(f'{o["before_bytes"]:.0f} → {o["after_bytes"]:.0f}' for o in r['orders']);out.append(f'| {r["mode"]} | {"Да" if equal else "Нет: появился перевод"} | {times} | {pct} | {allocation} |')
 out+=['','В двух new_* сценариях старая версия оставляет английский текст, новая переводит. Их проценты нельзя выдавать за ускорение или замедление одинаковой работы.','','### Контрольный повтор прежних сценариев','','Ещё четыре JVM, шесть одинаковых по полезной работе сценариев, 300 000 прогревочных и четыре раунда не менее 200 000 измеряемых вызовов. Это дополнительный опыт, не замена первых результатов.','','| Сценарий | До → после, мкс | Изменение | Байты до → после |','| --- | ---: | ---: | ---: |']
 for r in focused['summary']:
  times=' / '.join(f'{o["before_ns"]/1000:.3f} → {o["after_ns"]/1000:.3f}' for o in r['orders']);pct=' / '.join(f'{o["wall_change_percent"]:+.1f}%' for o in r['orders']);allocation=' / '.join(f'{o["before_bytes"]:.0f} → {o["after_bytes"]:.0f}' for o in r['orders']);out.append(f'| {r["mode"]} | {times} | {pct} | {allocation} |')
 changes=[o['wall_change_percent'] for r in focused['summary'] for o in r['orders']];deltas=[o['after_ns']-o['before_ns'] for r in focused['summary'] for o in r['orders']]
 out+=['',f'Диапазон длинного повтора: {min(changes):+.1f}%…{max(changes):+.1f}%. Максимальное положительное отклонение: {max(0,max(deltas))/1000:.3f} мкс на сообщение. Результаты не доказывают нулевую нагрузку или отсутствие микролагов в игре.','','## Что осталось','','6 235 строк без подтверждённого точного ключа: дальнейшие NPC, переменные, многострочные меню, извлечение/редакторские обозначения и исторические условия. Ни весь Абифон, ни все персонажи, ни вся игра не объявляются завершёнными.','','JAR не устанавливался автоматически; игра не перезапускалась.','',f'SHA-256 JAR: `{fingerprint}`.']
 return '\n'.join(out)+'\n'
